import { FileArchiveIcon, LoaderCircleIcon } from "lucide-react"

import { AdminFileUploadField } from "~/components/admin/admin-file-upload-field"
import { AdminField, adminControlClass } from "~/components/admin/admin-ui"
import type { SitePackageRuntimeMode } from "~/lib/api"

import { validateArchive, type UploadDraft } from "../site-package-model"

const archiveAccept = ".zip,application/zip,application/x-zip-compressed"

function archiveIssueLabel(message: string | null) {
  if (message === "页面包必须是 .zip 文件") return "格式不符"
  if (message === "页面包不能超过 80 MiB") return "文件过大"
  return null
}

export function UploadFields({
  disabled,
  draft,
  idPrefix,
  onChange,
}: {
  disabled: boolean
  draft: UploadDraft
  idPrefix: string
  onChange: (draft: UploadDraft) => void
}) {
  return (
    <div className="grid gap-5 sm:grid-cols-2">
      <AdminFileUploadField
        id={`${idPrefix}-archive`}
        name="archive"
        label="ZIP 页面包"
        description="最多 80 MiB；仅接收 HTML、CSS、字体、图片与受控脚本资源。"
        className="sm:col-span-2"
        accept={archiveAccept}
        emptyTitle="选择页面包归档"
        emptyDetail="ZIP 归档 · 最大 80 MiB"
        fileKind="ZIP 归档"
        file={draft.archive}
        disabled={disabled}
        required
        invalid={Boolean(draft.archive && validateArchive(draft.archive))}
        invalidLabel={archiveIssueLabel(
          draft.archive ? validateArchive(draft.archive) : null
        )}
        dropZoneLabel="页面包文件选择"
        dropTitle="松开以选择页面包"
        selectedIcon={FileArchiveIcon}
        onSelect={(archive) => onChange({ ...draft, archive })}
      />
      <AdminField
        label="入口文件"
        htmlFor={`${idPrefix}-entry-path`}
        description="必须位于 ZIP 根目录，例如 index.html。"
      >
        <input
          id={`${idPrefix}-entry-path`}
          className={adminControlClass}
          disabled={disabled}
          required
          value={draft.entryPath}
          onChange={(event) =>
            onChange({ ...draft, entryPath: event.target.value })
          }
        />
      </AdminField>
      <AdminField
        label="运行模式"
        htmlFor={`${idPrefix}-runtime-mode`}
        description="仅在页面确实需要脚本时启用隔离脚本模式。"
      >
        <select
          id={`${idPrefix}-runtime-mode`}
          className={adminControlClass}
          disabled={disabled}
          value={draft.runtimeMode}
          onChange={(event) =>
            onChange({
              ...draft,
              runtimeMode: event.target.value as SitePackageRuntimeMode,
            })
          }
        >
          <option value="safe">静态安全模式</option>
          <option value="isolated-script">隔离脚本模式</option>
        </select>
      </AdminField>
    </div>
  )
}

export function UploadProgress({ label }: { label: string }) {
  return (
    <div className="flex flex-col gap-2" role="status">
      <span className="inline-flex items-center gap-2 text-sm text-muted-foreground">
        <LoaderCircleIcon className="size-4 animate-spin" aria-hidden="true" />
        {label}
      </span>
      <progress
        aria-label={label}
        className="h-1 w-full overflow-hidden rounded bg-muted accent-primary"
      />
    </div>
  )
}
